head.script:
scwin.screenId = "jldfil25400";

///////// 1. 변수 및 선언 영역 /////////



///////// 2. 초기화 영역 /////////

// [A] 초기 목록 미해결 — 진입 근거가 다른 액션을 가리킨다(popnote vs note) — 어느 쪽인지 정할 근거가 없다


// 화면 전환 파라미터 수신 — 엔진 표준(§106). 진입 파라미터 전체를 컨텍스트 dataMap 에 담는다. onpageload 합성 단계.
/**
 * @method
 * @name scwin.init_recvParam
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

scwin.form_noteForm = { action: "", method: 'post', target: '' };

// 화면 진입점 — 초기화 단계를 데이터 의존 순서로 호출한다.
/**
 * @method
 * @name scwin.onpageload
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.onpageload = function () {
    try {
        scwin.init_recvParam();
    } catch (e) {
        $c.exception.handleError(e, { context: 'jldfil25400.onpageload' });
    }
};


///////// 3. 컴포넌트 이벤트 영역 /////////

/**
 * @event
 * @name scwin.listTable_oncellclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param rowIndex columnIndex columnId
 * @returns
 * @hidden N
*/
scwin.listTable_oncellclick = async function (rowIndex, columnIndex, columnId) {
    try {
        const dl = $c.util.getComponent('dlt_noteList');
        if (!dl) { console.error('[sdd] 행 동작 대상 목록 없음: dlt_noteList'); return; }
        const r = dl.getRowJSON ? dl.getRowJSON(rowIndex) : null;
        if (!r) { return; }
        if (typeof scwin.viewContents === 'function') { await scwin.viewContents(r["notiSvcId"], r["notiSeq"]); } else { console.error('[sdd] 행 동작 미정의: scwin.viewContents (열 ?)'); await $c.win.alert('이 행 동작을 아직 정하지 못했습니다(전환 미완) — scwin.viewContents'); } return;
    } catch (e) {
        await $c.exception.handleError(e, { notify: 'none', context: 'listTable.oncellclick' });
    }
};

/**
 * @event
 * @name scwin.divContn_cell_onclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param e
 * @returns
 * @hidden N
*/
scwin.divContn_cell_onclick = function(e){
    try {
        const ev = e;
        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        /* sdd-asis-lifecycle:begin divContn_cell_onclick — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        scwin.viewClose()
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil25400.divContn_cell_onclick' }); }
};


///////// 4. 서브미션 콜백 영역 /////////

/**
 * @method
 * @name scwin.tx_fn_Delete
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.tx_fn_Delete = async function () {
    const sbmOptions = {
        id: "tx_fn_Delete",
        method: "post",
        action: "/account/note.do",
        ref: "dma_DeleteReq",
        target: "dlt_noteList=body.content",
        isProcessMsg: false
    };
    let res = null;
    try { res = await $c.sbm.executeDynamic(sbmOptions); }
    catch (_e) { await $c.exception.handleError(_e, { context: "jldfil25400.tx_fn_Delete" }); return null; }
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
        return res;
    }

    return res;
};

/**
 * @method
 * @name scwin.tx_fn_ViewContents_xhr
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.tx_fn_ViewContents_xhr = async function () {
    // ⛔주소가 없다 — as-is 는 «자기 자신» 에게 제출했는데(`self_submit`) 화면 자신의 액션 URL 을
    //   하나로 못 정했다(후보 0 또는 여럿). 빈 주소로 내보내면 «조용히 엉뚱한 곳» 이다.
    throw { bizMessage: "이 화면의 제출 주소를 아직 정하지 못했습니다(전환 미완) — tx_fn_ViewContents_xhr", unresolved: "action:self_submit:tx_fn_ViewContents_xhr" };
};


///////// 5. 일반/업무 함수 영역 /////////

/**
 * @method
 * @name scwin.listTable_fmt_column1
 * @author Inswave
 * @date 2026. 09. 29
 * @param data formattedData r c
 * @returns
 * @hidden N
*/
scwin.listTable_fmt_column1 = async function (data, formattedData, r, c) {
    try {
        const dl = $c.util.getComponent("dlt_noteList");
        const v = String(dl && dl.getCellData ? (dl.getCellData(r, "readYn") ?? '') : '');
        if (v === 'Y') { return (console.error('[sdd] 미실현 라벨 갈래: column1 (image)'), String(data ?? '')); }
        return (console.error('[sdd] 미실현 라벨 갈래: column1 (image)'), String(data ?? ''));
    } catch (e) { await $c.exception.handleError(e, { notify: 'none', context: "listTable.column1" }); return String(data ?? ''); }
};

/**
 * @method
 * @name scwin.viewContents
 * @author Inswave
 * @date 2026. 09. 29
 * @param _notiSvcId _notiSeq
 * @returns
 * @hidden N
*/
scwin.viewContents = async function (_notiSvcId, _notiSeq) {
    /* sdd-asis-lifecycle:begin fn_ViewContents — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    $c.util.getComponent('dma_DeleteReq').set('notiSvcId', _notiSvcId);
    $c.util.getComponent('dma_DeleteReq').set('notiSeq', _notiSeq);
    scwin.form_noteForm.action = "/account/popNote.do";
    $c.util.getComponent('dma_DeleteReq').set('method', "noteDetail");
    await scwin.tx_fn_ViewContents_xhr();
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.deleteDeleteReq
 * @author Inswave
 * @date 2026. 09. 29
 * @param _notiSvcId _notiSeq
 * @returns
 * @hidden N
*/
scwin.deleteDeleteReq = async function (_notiSvcId, _notiSeq) {
    /* sdd-asis-lifecycle:begin fn_Delete — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    $c.util.getComponent('dma_DeleteReq').set('notiSvcId', _notiSvcId);
    $c.util.getComponent('dma_DeleteReq').set('notiSeq', _notiSeq);
    scwin.form_noteForm.action = "/account/note.do";
    $c.util.getComponent('dma_DeleteReq').set('method', "deleteNote");
    await scwin.tx_fn_Delete();
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.onCompleteResponse
 * @author Inswave
 * @date 2026. 09. 29
 * @param responseText
 * @returns
 * @hidden N
*/
scwin.onCompleteResponse = function (responseText) {
    /* sdd-asis-lifecycle:begin onCompleteResponse — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const viewDiv = $c.util.getComponent('txt_divContn');
    (!viewDiv ? console.warn('[sdd] 표시 전환 대상 미해결: viewDiv') : (('inline') === 'none' ? (viewDiv.hide ? viewDiv.hide() : void 0) : (viewDiv.show ? viewDiv.show() : void 0)));
    viewDiv.setStyle('left', $c.util.getComponent('listTable').getBoundingClientRect().left + 105);
    viewDiv.setStyle('top', document.body.scrollTop + event.clientY + 10);
    viewDiv.innerHTML = responseText;
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.viewClose
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.viewClose = function () {
    /* sdd-asis-lifecycle:begin fn_ViewClose — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const viewDiv = $c.util.getComponent('txt_divContn');
    (!viewDiv ? console.warn('[sdd] 표시 전환 대상 미해결: viewDiv') : (('none') === 'none' ? (viewDiv.hide ? viewDiv.hide() : void 0) : (viewDiv.show ? viewDiv.show() : void 0)));
    /* sdd-asis-lifecycle:end */
};
